pub fn method_owner_class_node<'a>(&self, func_node: &Node<'a>) -> Option<Node<'a>> {
    match self {
        Language::Python => {
            let mut n = *func_node;
            if let Some(p) = n.parent() {
                if p.kind() == "decorated_definition" {
                    n = p;
                }
            }
            let block = n.parent()?;
            if block.kind() != "block" {
                return None;
            }
            let cls = block.parent()?;
            (cls.kind() == "class_definition").then_some(cls)
        }
        Language::JavaScript | Language::TypeScript | Language::Tsx => {
            let mut body = func_node.parent()?;
            if matches!(body.kind(), "field_definition" | "public_field_definition") {
                body = body.parent()?;
            }
            if body.kind() != "class_body" {
                return None;
            }
            let cls = body.parent()?;
            matches!(cls.kind(), "class_declaration" | "class").then_some(cls)
        }
        _ => None,
    }
}

/// S3 (Rust): for `impl Trait for Type`, the trait name node (dual-key).
pub fn rust_impl_trait<'a>(&self, func_node: &Node<'a>) -> Option<Node<'a>> {
    if !matches!(self, Language::Rust) {
        return None;
    }
    let mut anc = func_node.parent();
    while let Some(n) = anc {
        match n.kind() {
            "impl_item" => return n.child_by_field_name("trait"),
            "function_item" | "closure_expression" => return None,
            _ => {}
        }
        anc = n.parent();
    }
    None
}

/// Rust: enclosing item for a method definition (`trait_item` or `impl_item`).
pub fn rust_enclosing_method_item<'a>(&self, func_node: &Node<'a>) -> Option<Node<'a>> {
    if !matches!(self, Language::Rust) {
        return None;
    }
    let mut anc = func_node.parent();
    while let Some(n) = anc {
        match n.kind() {
            "impl_item" | "trait_item" => return Some(n),
            "function_item" | "closure_expression" => return None,
            _ => {}
        }
        anc = n.parent();
    }
    None
}

/// Rust: ordered method parameters, including a leading `self` parameter when present.
pub fn method_params<'a>(&self, func_node: &Node<'a>) -> Vec<Node<'a>> {
    if !matches!(self, Language::Rust) {
        return Vec::new();
