/// interface name. Returns `None` for a generic instantiation (`Foo[T]`), which
/// is non-dispatchable (a recorded gap, never a key) — spec §6/§10.
pub fn iface_key(text: &str) -> Option<String> {
    let t = text
        .trim()
        .trim_start_matches('&')
        .trim_start_matches('*')
        .trim();
    if t.contains('[') {
