import ast, os, sys, collections

def base_name(node):
    # class C(Base) / C(pkg.mod.Base) / C(Generic[T]) -> "Base"/"Base"/"Generic"
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Subscript):
        return base_name(node.value)
    return None

class ClassRec:
    __slots__=("name","file","line","bases","methods")
    def __init__(self,name,file,line,bases,methods):
        self.name=name; self.file=file; self.line=line
        self.bases=bases; self.methods=methods

def collect(root):
    # bare class name -> list of ClassRec (models prism's name-keyed methods + collisions)
    table=collections.defaultdict(list)
    files=[]
    for dp,_,fns in os.walk(root):
        if any(s in dp for s in ("/.venv","/venv","/node_modules","/.git","/tests","/test")): continue
        for fn in fns:
            if fn.endswith(".py"): files.append(os.path.join(dp,fn))
    recs=[]
    for f in files:
        try:
            src=open(f,encoding="utf-8",errors="ignore").read()
            tree=ast.parse(src)
        except Exception: continue
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                bases=[b for b in (base_name(x) for x in node.bases) if b]
                methods=set()
                for b in node.body:
                    if isinstance(b,(ast.FunctionDef,ast.AsyncFunctionDef)):
                        methods.add(b.name)
                rec=ClassRec(node.name,f,node.lineno,bases,methods)
                table[node.name].append(rec); recs.append((f,node))
    return table, files

def ancestors_defining(table, rec, meth, seen):
    # DFS over in-repo bases (bare-name), collect (class,file) that define meth. seen=cycle guard
    hits=[]; ambiguous_base=False; had_external_base=False; had_base=bool(rec.bases)
    for b in rec.bases:
        cands=table.get(b)
        if not cands:
            had_external_base=True; continue
        # prefer same-file base, else all in-repo same-name (ambiguity)
        same=[c for c in cands if c.file==rec.file]
        pool = same if same else cands
        if len(pool)>1: ambiguous_base=True
        for c in pool:
            key=(c.file,c.line)
            if key in seen: continue
            seen.add(key)
            if meth in c.methods:
                hits.append((c.name,c.file))
            sub_hits,sub_amb,sub_ext,_=ancestors_defining(table,c,meth,seen)
            hits.extend(sub_hits); ambiguous_base=ambiguous_base or sub_amb
            had_external_base=had_external_base or sub_ext
    return hits, ambiguous_base, had_external_base, had_base

def analyze(root):
    table,files=collect(root)
    cats=collections.Counter()
    inh_unambig=0; inh_ambig=0
    examples=[]
    for f in files:
        try: tree=ast.parse(open(f,encoding="utf-8",errors="ignore").read())
        except Exception: continue
        for cls in ast.walk(tree):
            if not isinstance(cls,ast.ClassDef): continue
            # find THIS rec
            rec=None
            for c in table.get(cls.name,[]):
                if c.file==f and c.line==cls.lineno: rec=c; break
            if rec is None: continue
            for sub in ast.walk(cls):
                if isinstance(sub,ast.Call) and isinstance(sub.func,ast.Attribute) \
                   and isinstance(sub.func.value,ast.Name) and sub.func.value.id=="self":
                    X=sub.func.attr
                    if X in rec.methods:
                        cats["own_1a"]+=1; continue
                    hits,amb,ext,hadbase=ancestors_defining(table,rec,X,set())
                    uniq={(n,fl) for n,fl in hits}
                    if uniq:
                        cats["inherited_in_repo_1b"]+=1
                        if len(uniq)==1 and not amb:
                            inh_unambig+=1
                            if len(examples)<12: examples.append((os.path.relpath(f,root),cls.name,X,list(uniq)[0][0]))
                        else: inh_ambig+=1
                    elif not hadbase:
                        cats["no_base_dynamic"]+=1
                    elif ext:
                        cats["external_base_scip"]+=1
                    else:
                        cats["inrepo_base_no_method"]+=1
    total=sum(cats.values())
    print(f"\n===== {root} =====")
    print(f"total self.X() call sites: {total}")
    for k in ["own_1a","inherited_in_repo_1b","external_base_scip","no_base_dynamic","inrepo_base_no_method"]:
        print(f"  {k:26s}: {cats[k]:5d}  ({100*cats[k]/max(total,1):.1f}%)")
    print(f"  1b breakdown: unambiguous(Exact-eligible)={inh_unambig}  ambiguous(demote)={inh_ambig}")
    print(f"  --> 1B BUY (in-repo inherited self.X()): {cats['inherited_in_repo_1b']}")
    print("  examples (file, class, self.X, defining-ancestor):")
    for e in examples: print("    ",e)
    return cats

for r in sys.argv[1:]:
    analyze(r)

